package com.littlemakers.village.nativeapp;
import android.content.Context;import android.graphics.*;import android.view.*;import java.util.*;
/** Transparent tactile and accessible-input companion to the native 3D scene. */
final class StudioBoardView extends View {
 interface Listener{void changed();void trace(int percent,boolean done);void cell(int slot);void stop(int slot);}
 final int mode;final ThemeManager theme;final Listener listener;final TangramState tangram;
 final Paint paint=new Paint(3);final Path guide=new Path(),ink=new Path();TraceTrack trace;private float lastX,lastY,offsetX,offsetY;private int drag=-1;boolean[]stops=new boolean[24];int selected;boolean tracingDone;
 StudioBoardView(Context c,int mode,ThemeManager theme,TangramState tangram,String letter,Listener l){super(c);this.mode=mode;this.theme=theme;this.tangram=tangram;listener=l;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);if(letter!=null)makeTrace(letter);}
 private void makeTrace(String letter){paint.setTypeface(theme.font(true));paint.setTextSize(275);paint.getTextPath(letter,0,letter.length(),0,0,guide);RectF box=new RectF();guide.computeBounds(box,true);Matrix m=new Matrix();m.setTranslate(320-box.centerX(),190-box.centerY());guide.transform(m);ArrayList<Float>points=new ArrayList<>();PathMeasure measure=new PathMeasure(guide,false);float[]xy=new float[2];do{for(float d=0;d<measure.getLength();d+=9){measure.getPosTan(d,xy,null);points.add(xy[0]);points.add(xy[1]);}}while(measure.nextContour());float[]p=new float[points.size()];for(int i=0;i<p.length;i++)p[i]=points.get(i);trace=new TraceTrack(p);}
 static Path polygon(int kind,float size){Path p=new Path();if(kind==9){p.moveTo(-size,-size);p.lineTo(size,-size);p.lineTo(-size,size);}else if(kind==10){p.moveTo(-size,-size*.65f);p.lineTo(size*.35f,-size*.65f);p.lineTo(size,size*.65f);p.lineTo(-size*.35f,size*.65f);}else{p.addRect(-size,-size,size,size,Path.Direction.CW);}p.close();return p;}
 @Override protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/640f,getHeight()/420f);paint.setTypeface(theme.font(true));paint.setStrokeWidth(3);paint.setPathEffect(null);if(mode==1&&trace!=null){paint.setStyle(Paint.Style.FILL);paint.setColor(theme.dark?0xff485779:0xffd8ccec);c.drawPath(guide,paint);paint.setStyle(Paint.Style.STROKE);paint.setColor(theme.text);paint.setStrokeWidth(3);paint.setPathEffect(new DashPathEffect(new float[]{9,9},0));c.drawPath(guide,paint);paint.setPathEffect(null);paint.setColor(theme.dark?0xffffd882:0xff8052a4);paint.setStrokeWidth(14);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeJoin(Paint.Join.ROUND);c.drawPath(ink,paint);paint.setStyle(Paint.Style.FILL);for(int i=0;i<trace.samples();i++)if(trace.covered(i))c.drawCircle(trace.x(i),trace.y(i),5,paint);paint.setStrokeCap(Paint.Cap.BUTT);}else if(mode==4){for(int i=0;i<7;i++){c.save();c.translate(tangram.tx(i),tangram.ty(i));c.rotate(tangram.targetRotation(i)*45);paint.setStyle(Paint.Style.STROKE);paint.setColor(theme.dark?0xffe2eafd:0xff344565);paint.setStrokeWidth(3);c.drawPath(polygon(TangramState.KIND[i],TangramState.SIZE[i]),paint);c.restore();paint.setStyle(Paint.Style.FILL);paint.setTextSize(17);paint.setColor(theme.text);c.drawText(""+(i+1),tangram.tx(i)-5,tangram.ty(i)+TangramState.SIZE[i]+22,paint);}if(tangram.placed[tangram.selected]<0){paint.setStyle(Paint.Style.STROKE);paint.setColor(theme.dark?0xffffdc85:0xff694987);paint.setStrokeWidth(4);c.drawCircle(tangram.x[tangram.selected],tangram.y[tangram.selected],TangramState.SIZE[tangram.selected]+9,paint);}}else if(mode==2||mode==5){paint.setStyle(Paint.Style.FILL);paint.setTextSize(20);for(int i=0;i<24;i++){float x=mode==2?ExplorerScenes.mapX(i):cellX(i),y=cellY(i);paint.setColor(theme.text);c.drawText(mode==2?(stops[i]?"✓":""+(i+1)):""+(i+1),mode==2?x-8:x-37,mode==2?y+6:y-24,paint);if(i==selected){paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(4);c.drawCircle(x,y,mode==2?31:39,paint);paint.setStyle(Paint.Style.FILL);}}}c.restore();}
 static float cellX(int i){return 80+i%6*96;}static float cellY(int i){return 60+i/6*88;}
 private int hit(float x,float y){for(int i=6;i>=0;i--)if(tangram.placed[i]<0&&Math.hypot(x-tangram.x[i],y-tangram.y[i])<TangramState.SIZE[i]*1.45+10)return i;return -1;}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){float x=e.getX()*640/Math.max(1,getWidth()),y=e.getY()*420/Math.max(1,getHeight());int action=e.getActionMasked();if(action==android.view.MotionEvent.ACTION_DOWN){lastX=x;lastY=y;if(mode==1&&trace!=null&&!tracingDone){ink.moveTo(x,y);getParent().requestDisallowInterceptTouchEvent(true);return true;}if(mode==4){drag=hit(x,y);if(drag>=0){tangram.selected=drag;offsetX=x-tangram.x[drag];offsetY=y-tangram.y[drag];getParent().requestDisallowInterceptTouchEvent(true);listener.changed();return true;}}return mode==2||mode==5;}if(action==android.view.MotionEvent.ACTION_MOVE){if(mode==1&&trace!=null&&!tracingDone){trace.stroke(lastX,lastY,x,y,19);ink.lineTo(x,y);lastX=x;lastY=y;invalidate();listener.trace(trace.percent(),trace.complete());return true;}if(drag>=0){tangram.x[drag]=Math.max(30,Math.min(610,x-offsetX));tangram.y[drag]=Math.max(45,Math.min(385,y-offsetY));listener.changed();return true;}return mode==2||mode==5;}if(action==android.view.MotionEvent.ACTION_UP||action==android.view.MotionEvent.ACTION_CANCEL){getParent().requestDisallowInterceptTouchEvent(false);if(mode==1&&trace!=null&&!tracingDone){if(action==android.view.MotionEvent.ACTION_UP){trace.stroke(lastX,lastY,x,y,19);ink.lineTo(x,y);listener.trace(trace.percent(),trace.complete());}invalidate();performClick();return true;}if(drag>=0){if(action==android.view.MotionEvent.ACTION_UP)tangram.drop(drag,x-offsetX,y-offsetY);else{tangram.x[drag]=50+drag*89;tangram.y[drag]=355;}drag=-1;listener.changed();performClick();return true;}if(action==android.view.MotionEvent.ACTION_UP&&(mode==2||mode==5)&&Math.hypot(x-lastX,y-lastY)<30){int nearest=-1;double distance=58;for(int i=0;i<24;i++){double d=Math.hypot(x-(mode==2?ExplorerScenes.mapX(i):cellX(i)),y-cellY(i));if(d<distance){distance=d;nearest=i;}}if(nearest>=0){selected=nearest;if(mode==2)listener.stop(nearest);else listener.cell(nearest);}performClick();return true;}}return false;}
 @Override public boolean performClick(){super.performClick();return true;}
}
